import { controlStyles } from "@/components/ui/kalos-styles";
import type { ReactNode } from "react";
import { Badge } from "@/components/ui/badge";
export function KalosBadge({
  status = "neutral",
  children,
}: {
  status?: "neutral" | "success" | "warning";
  children: ReactNode;
}) {
  return (
